steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { number: { eq: 1 }, team: { key: { eq: \"WEB\" } } }) { nodes { id identifier title url } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { comments(filter: { issue: { id: { eq: \"i-web-1\" } } }) { nodes { id body createdAt updatedAt user { name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { comments(filter: { issue: { id: { eq: \"i-web-1\" } } }) { nodes { id body createdAt updatedAt user { name } history { node { body createdAt } } } } }"
  }'
